UNIT_PREFIX_PATTERNS = (
    re.compile(
        r"^(?P<unit>[A-Z0-9]{2,8})/[A-Z0-9]{2,8}/\d{4}/\d{4,}$",
        re.IGNORECASE,
    ),
    re.compile(r"^(?P<unit>[A-Z0-9]{2,8})/\d{4}/\d{4,}$", re.IGNORECASE),
)


def backfill_student_home_units(apps, schema_editor):
    Student = apps.get_model("people", "Student")
    BusinessUnit = apps.get_model("org", "BusinessUnit")
    database = schema_editor.connection.alias
    students = list(
        Student.objects.using(database)
        .select_related("department__unit")
        .order_by("pk")
    )
    units_by_code = {
        unit.code.upper(): unit.pk
        for unit in BusinessUnit.objects.using(database).all()
    }

    mapped = []
    prefix_count = 0
    department_fallback_count = 0
    unmapped = []
    for student in students:
        prefix = next(
            (
                match.group("unit").upper()
                for pattern in UNIT_PREFIX_PATTERNS
                if (match := pattern.fullmatch(student.registration_number.strip()))
            ),
            None,
        )
        if prefix:
            unit_id = units_by_code.get(prefix)
            if unit_id is None:
                unmapped.append((student.pk, student.registration_number, prefix))
                continue
            prefix_count += 1
        else:
            unit_id = student.department.unit_id
            if unit_id is None:
                unmapped.append(
                    (student.pk, student.registration_number, "department has no unit")
                )
                continue
            department_fallback_count += 1
        mapped.append((student.pk, unit_id))

    print(
        "D9 home-unit preflight: "
        f"students={len(students)}, registration-prefix={prefix_count}, "
        f"department-fallback={department_fallback_count}, unmappable={len(unmapped)}"
    )
    if unmapped:
        details = "; ".join(
            f"student={student_id}, registration_number={registration_number}, "
            f"reason={reason}"
            for student_id, registration_number, reason in unmapped
        )
        raise RuntimeError(f"Unable to map Student.home_unit: {details}")

    Student.objects.using(database).bulk_update(
        [
            Student(pk=student_id, home_unit_id=unit_id)
            for student_id, unit_id in mapped
        ],
        ("home_unit",),
    )


